const sessionId = $input.first().json.sessionId || 'session-' + Date.now();
const timestamp = new Date().toISOString();
const agentOutput = $input.first().json.output || '';

// Extract framework classification
const frameworkMatch = agentOutput.match(/\*\*Detected Framework:\*\* (.+)/);
const confidenceMatch = agentOutput.match(/\*\*Confidence:\*\* (.+)/);
const framework = frameworkMatch ? frameworkMatch[1].trim() : 'UNKNOWN';
const confidence = confidenceMatch ? confidenceMatch[1].trim() : 'UNKNOWN';

// Count artifacts
const artifactRows = (agentOutput.match(/\| \d+ \|/g) || []).length;

// Detect guardrail trigger
const guardrailTriggered = agentOutput.includes('unable to determine') ? 'Y' : 'N';

const logEntry = {
  timestamp,
  session_id: sessionId,
  agent: 'Task2_RouterAgent',
  framework_detected: framework,
  confidence: confidence,
  artifact_count: artifactRows,
  guardrail_triggered: guardrailTriggered,
  outcome: 'Pending_PM_Approval'
};

return [{ json: { logEntry, agentOutput, sessionId } }];

const logEntry = $input.first().json.logEntry;
const feedback = $input.first().json.chatInput || '';
logEntry.outcome = 'Revision_Requested';
logEntry.pm_feedback = feedback;
return [{ json: { ...$input.first().json, logEntry, feedback } }];
